import React, { useEffect, useState } from 'react';
import { ShoppingCart } from 'lucide-react';

interface NavbarProps {
    onOpenPayment: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ onOpenPayment }) => {
    const [scrolled, setScrolled] = useState(false);

    useEffect(() => {
        const handleScroll = () => {
            if (window.scrollY > 20) {
                setScrolled(true);
            } else {
                setScrolled(false);
            }
        };

        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    return (
        <nav 
            id="navbar" 
            className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 border-b ${
                scrolled 
                ? 'bg-white/95 backdrop-blur-md border-gray-200 py-2 shadow-sm' 
                : 'bg-transparent border-transparent py-4'
            }`}
        >
            <div className="max-w-7xl mx-auto px-6 flex justify-between items-center w-full">

                {/* LEFT: Logo & Text */}
                <div className="flex items-center gap-4">
                    <img 
                        src="https://ufoweb.de/eins/original-logo-to-replace-the-old-one.jpg" 
                        alt="Das Einmaleins ist meins Logo" 
                        className="h-12 w-auto object-contain drop-shadow-sm" 
                    />
                    <span className={`font-serif font-bold text-xl tracking-tight text-brand-charcoal leading-none pt-1 hidden sm:block transition-opacity duration-300 ${scrolled ? 'opacity-100' : 'opacity-90'}`}>
                        Das Einmaleins ist meins!
                    </span>
                </div>

                {/* RIGHT: Action Button */}
                <div>
                    <button 
                        onClick={onOpenPayment}
                        className={`flex items-center gap-2 font-bold transition-all duration-300 px-5 py-2.5 rounded-lg shadow-sm hover:shadow-md transform active:scale-95 text-sm uppercase tracking-wide
                        ${scrolled 
                            ? 'bg-brand-orange text-white hover:bg-brand-terracotta' 
                            : 'bg-white text-brand-charcoal hover:bg-gray-50 border border-brand-charcoal/10'
                        }`}
                    >
                        <span>Bestellen</span>
                        <ShoppingCart className="w-4 h-4" />
                    </button>
                </div>

            </div>
        </nav>
    );
};

