import React, { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface CarouselProps {
    title: string;
    folderName: string;
}

const StoryCarousel: React.FC<CarouselProps> = ({ title, folderName }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const totalImages = 11;

    // Generate images 01.jpg to 11.jpg
    const images = Array.from({ length: totalImages }, (_, i) => {
        const num = String(i + 1).padStart(2, '0');
        return `https://ufoweb.de/eins/${folderName}/${num}.jpg`;
    });

    const nextSlide = () => {
        setCurrentIndex((prev) => (prev + 1) % totalImages);
    };

    const prevSlide = () => {
        setCurrentIndex((prev) => (prev - 1 + totalImages) % totalImages);
    };

    return (
        <div className="bg-white rounded-[2rem] p-6 shadow-xl border border-gray-100 flex flex-col h-full hover:shadow-2xl transition-shadow duration-300">
            <h3 className="text-lg font-serif font-bold text-brand-charcoal mb-4 text-center min-h-[3rem] flex items-center justify-center">
                {title}
            </h3>

            <div className="relative bg-brand-cream/30 rounded-xl overflow-hidden aspect-[3/4] group border border-gray-100">
                {/* Image */}
                <img 
                    src={images[currentIndex]} 
                    alt={`${title} Seite ${currentIndex + 1}`} 
                    className="w-full h-full object-contain"
                />

