import React, { useRef, useState } from 'react';
import { Volume2, VolumeX, Check, Loader2, Play } from 'lucide-react';

interface ProblemSolutionProps {
    onOpenPayment: () => void;
}

export const ProblemSolution: React.FC<ProblemSolutionProps> = ({ onOpenPayment }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isMuted, setIsMuted] = useState(true);
    const [isLoading, setIsLoading] = useState(false);
    const [hasStarted, setHasStarted] = useState(false);

    const handlePlayClick = () => {
        setHasStarted(true);
        setIsLoading(true);
        if (videoRef.current) {
            videoRef.current.load();
            videoRef.current.play().catch(error => {
                console.log("Play failed:", error);
                setIsLoading(false);
            });
        }
    };

    const toggleAudio = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (videoRef.current) {
            videoRef.current.muted = !videoRef.current.muted;
            setIsMuted(videoRef.current.muted);
        }
    };

    return (
        <section className="py-16 px-6 max-w-7xl mx-auto">
            {/* Video Showcase Box - Lighter Purple */}
            <div className="bg-brand-purple-fresh text-white rounded-[3rem] p-8 md:p-16 relative overflow-hidden shadow-xl">
                <div className="grid md:grid-cols-2 gap-12 items-center relative z-10">
                    <div className="flex justify-center">
                        <div 
                            className="relative w-full max-w-[280px] aspect-[9/16] bg-black rounded-[2.5rem] border-[8px] border-white/20 shadow-2xl overflow-hidden cursor-pointer group"
                            onClick={hasStarted ? toggleAudio : handlePlayClick}
                        >
                            {/* Initial State Overlay: Poster + Play Button */}
                            {!hasStarted && (
                                <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/20 group-hover:bg-black/10 transition-colors">
                                    <img 
                                        src="https://ufoweb.de/eins/img/101.jpg" 
                                        alt="Video Vorschau" 
                                        className="absolute inset-0 w-full h-full object-cover -z-10"
                                    />
                                    <div className="bg-brand-orange/90 backdrop-blur-sm text-white p-5 rounded-full shadow-xl transform transition-all duration-300 group-hover:scale-110 group-hover:bg-brand-orange mb-4">
                                        <Play className="w-8 h-8 fill-current ml-1" />
                                    </div>
                                    <span className="text-white font-bold text-sm uppercase tracking-wider drop-shadow-md bg-black/30 px-3 py-1 rounded-full backdrop-blur-sm">
                                        Video ansehen
                                    </span>
                                </div>
                            )}

                            {/* Loading Overlay */}
                            {isLoading && hasStarted && (
                                <div className="absolute inset-0 flex flex-col items-center justify-center bg-brand-charcoal/90 backdrop-blur-sm z-20">
                                    <Loader2 className="w-8 h-8 text-white animate-spin mb-2" />
                                    <span className="text-white font-bold text-xs tracking-wide uppercase">Video lädt...</span>
                                </div>
                            )}

                            <video 
                                ref={videoRef}
                                muted={isMuted}
                                loop 
                                playsInline 
                                preload="none"
                                className={`w-full h-full object-cover transition-opacity duration-500 ${hasStarted ? 'opacity-100' : 'opacity-0'}`}
                                onCanPlay={() => setIsLoading(false)}
                                onLoadedData={() => setIsLoading(false)}
                                onWaiting={() => setIsLoading(true)}
                                onPlaying={() => setIsLoading(false)}
                            >
                                <source src="https://ufoweb.de/eins/img/video1.mp4" type="video/mp4" />
                                Ihr Browser unterstützt dieses Video nicht.
                            </video>

                            {/* Audio Indicator - Only show when playing */}
                            {hasStarted && !isLoading && (
                                <div className="absolute bottom-4 right-4 bg-black/50 p-2 rounded-full backdrop-blur-md transition-opacity opacity-0 group-hover:opacity-100 pointer-events-none z-10">
                                    {isMuted ? <VolumeX className="w-5 h-5 text-white" /> : <Volume2 className="w-5 h-5 text-white" />}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="text-center md:text-left space-y-8">
                        <div>
                            <h2 className="text-3xl md:text-5xl font-serif font-bold leading-tight mb-4">
                                Hier ein kleiner Einblick:
                            </h2>
                            <p className="text-white/90 text-lg leading-relaxed font-medium">
                                Sehen Sie, wie die bunten Bildkarten und Reime das Lernen unterstützen. Die Kombination aus visuellen und auditiven Reizen fördert die <span className="font-bold text-brand-yellow">Merkfähigkeit</span> nachhaltig.
                            </p>
                        </div>

                        <ul className="space-y-4 inline-block text-left">
                            <li className="flex items-center gap-4 text-base md:text-lg text-white/90">
                                <div className="bg-brand-orange/40 p-1 rounded-full text-white border border-white/20"><Check className="w-3.5 h-3.5" /></div> Handliches Kartenformat
                            </li>
                            <li className="flex items-center gap-4 text-base md:text-lg text-white/90">
                                <div className="bg-brand-orange/40 p-1 rounded-full text-white border border-white/20"><Check className="w-3.5 h-3.5" /></div> Hochwertiger Druck
                            </li>
                            <li className="flex items-center gap-4 text-base md:text-lg text-white/90">
                                <div className="bg-brand-orange/40 p-1 rounded-full text-white border border-white/20"><Check className="w-3.5 h-3.5" /></div> Intuitives Lernen
                            </li>
                            <li className="flex items-center gap-4 text-base md:text-lg text-white/90">
                                <div className="bg-brand-orange/40 p-1 rounded-full text-white border border-white/20"><Check className="w-3.5 h-3.5" /></div> Inklusive Testkarten
                            </li>
                        </ul>
                    </div>
                </div>
            </div>
        </section>
    );
};

