                            {/* Loading Overlay */}
                            {isLoading && hasStarted && (
                                <div className="absolute inset-0 flex flex-col items-center justify-center bg-brand-charcoal/90 backdrop-blur-sm z-20">
                                    <Loader2 className="w-8 h-8 text-white animate-spin mb-2" />
