import React, { useState, useEffect } from 'react';
import { GALLERY_IMAGES } from '../constants';
import { X, ChevronLeft, ChevronRight } from 'lucide-react';

export const Gallery: React.FC = () => {
    const [lightboxOpen, setLightboxOpen] = useState(false);
    const [currentIndex, setCurrentIndex] = useState(0);

    const openLightbox = (index: number) => {
        setCurrentIndex(index);
        setLightboxOpen(true);
        document.body.style.overflow = 'hidden';
    };

    const closeLightbox = () => {
        setLightboxOpen(false);
        document.body.style.overflow = '';
    };

    const nextImage = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex((prev) => (prev + 1) % GALLERY_IMAGES.length);
    };

    const prevImage = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex((prev) => (prev - 1 + GALLERY_IMAGES.length) % GALLERY_IMAGES.length);
    };

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (!lightboxOpen) return;
            if (e.key === 'Escape') closeLightbox();
            if (e.key === 'ArrowRight') nextImage();
            if (e.key === 'ArrowLeft') prevImage();
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [lightboxOpen]);

    return (
        <>
            <section className="py-16 bg-brand-cream overflow-hidden">
                <div className="max-w-7xl mx-auto px-6">
                    <h2 className="text-3xl md:text-5xl font-serif font-bold mb-12 text-center text-brand-dark leading-tight">Galerie</h2>
                    <div className="columns-2 md:columns-3 gap-6 space-y-6">
                        {GALLERY_IMAGES.map((img, idx) => (
                            <div 
                                key={img.id} 
                                className="relative group cursor-zoom-in rounded-3xl overflow-hidden shadow-md break-inside-avoid" 
                                onClick={() => openLightbox(idx)}
                            >
                                <div className="absolute inset-0 bg-black/20 group-hover:bg-black/0 transition-colors z-10"></div>
                                <img src={img.src} alt={`Gallery ${idx + 1}`} className="w-full h-auto object-cover transition-transform duration-700 group-hover:scale-110" />
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* Lightbox Modal */}
            {lightboxOpen && (
                <div 
                    className="fixed inset-0 z-[60] bg-black/90 backdrop-blur-md flex items-center justify-center p-4"
                    onClick={closeLightbox}
                >
                    <button 
                        onClick={(e) => { e.stopPropagation(); closeLightbox(); }} 
                        className="absolute top-6 right-6 text-white/70 hover:text-white transition-colors"
                    >
                        <X className="w-8 h-8" />
                    </button>

                    <button 
                        onClick={prevImage} 
                        className="absolute left-4 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all hover:scale-110 hidden md:block"
                    >
                        <ChevronLeft className="w-8 h-8" />
                    </button>

                    <div className="relative w-full max-w-5xl h-[80vh] flex items-center justify-center" onClick={(e) => e.stopPropagation()}>
                        <img 
                            src={GALLERY_IMAGES[currentIndex].src} 
                            alt="Gallery Item" 
                            className="max-w-full max-h-full object-contain rounded-md shadow-2xl" 
                        />
                        <div className="absolute bottom-[-3rem] left-0 right-0 text-center text-white/80 font-medium">
                            Bild {currentIndex + 1} von {GALLERY_IMAGES.length}
                        </div>
                    </div>

                    <button 
                        onClick={nextImage} 
                        className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all hover:scale-110 hidden md:block"
                    >
                        <ChevronRight className="w-8 h-8" />
                    </button>
                </div>
            )}
        </>
    );
};

