import React, { useState, useMemo, useEffect } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface CarouselProps {
    title: string;
    folderName: string;
}

const StoryCarousel: React.FC<CarouselProps> = ({ title, folderName }) => {
    const [currentIndex, setCurrentIndex] = useState(0);
    const totalImages = 11;

    // Memoize image array to prevent regeneration on render
    const images = useMemo(() => Array.from({ length: totalImages }, (_, i) => {
        const num = String(i + 1).padStart(2, '0');
        return `https://ufoweb.de/eins/${folderName}/${num}.jpg`;
    }), [folderName]);

    // Preload next image for smoother transitions
    useEffect(() => {
        const nextIndex = (currentIndex + 1) % totalImages;
        const img = new Image();
        img.src = images[nextIndex];
    }, [currentIndex, images]);

    const nextSlide = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex((prev) => (prev + 1) % totalImages);
    };

    const prevSlide = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        setCurrentIndex((prev) => (prev - 1 + totalImages) % totalImages);
    };

    return (
        <div className="bg-white rounded-[2rem] p-4 shadow-xl border border-gray-100 flex flex-col h-full hover:shadow-2xl transition-shadow duration-300">
            {/* Image Container: Clickable to advance - Auto height to fit image exactly */}
            <div 
                className="relative bg-brand-cream/30 rounded-xl overflow-hidden group border border-gray-100 cursor-pointer flex-grow flex items-center bg-gray-50"
                onClick={nextSlide}
            >
                <img 
                    src={images[currentIndex]} 
                    alt={`${title} Seite ${currentIndex + 1}`} 
                    className="w-full h-auto object-contain"
                />

                {/* Hover Arrows (Desktop) */}
                <div className="absolute inset-0 flex items-center justify-between p-2 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                     <button 
                        onClick={prevSlide}
                        className="bg-white/90 hover:bg-white text-brand-charcoal p-2 rounded-full shadow-md backdrop-blur-sm transition-transform active:scale-95 pointer-events-auto"
                    >
                        <ChevronLeft className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={nextSlide}
                        className="bg-white/90 hover:bg-white text-brand-charcoal p-2 rounded-full shadow-md backdrop-blur-sm transition-transform active:scale-95 pointer-events-auto"
                    >
                        <ChevronRight className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Controls Bar: Compact spacing */}
            <div className="flex items-center justify-between mt-2 px-1 shrink-0">
                <button 
                     onClick={prevSlide}
                     className="text-brand-charcoal/40 hover:text-brand-charcoal transition-colors p-1"
                     aria-label="Previous page"
                >
                    <ChevronLeft className="w-5 h-5" />
                </button>

                <span className="text-xs font-bold text-brand-charcoal bg-brand-stone/60 px-3 py-1 rounded-full">
                    Seite {currentIndex + 1} / {totalImages}
                </span>

                <button 
                     onClick={nextSlide}
                     className="text-brand-charcoal/40 hover:text-brand-charcoal transition-colors p-1"
                     aria-label="Next page"
